//! Keystrokes, the action registry and the default bindings. Knows nothing about the UI
//! toolkit: the view turns its key events into `Keystroke` and runs the action by name.
//!
//! The defaults are the IntelliJ IDEA keymap for Windows, read from `idea-default.json`.
//! That file is generated by `cargo xtask idea-keymap` and keeps IDEA's action ids; the
//! tables in [`editor`] and [`workspace`] say which of them the IDE implements.

mod dispatch;
mod gesture;
mod idea;
mod keymap_file;
mod keystroke;

